mapper.select:
SELECT pg.*, ll.lian_lu_name AS lianLuName, gl.guan_lang_name AS guanLangName
FROM t_zgsq_pei_guang pg
LEFT JOIN t_zgsq_lian_lu ll ON pg.lian_lu_id = ll.lian_lu_id AND ll.deleted = 0
LEFT JOIN t_zgsq_guan_lang gl ON pg.guan_lang_id = gl.guan_lang_id AND gl.deleted = 0
WHERE pg.deleted = 0

    AND pg.pei_guang_no LIKE CONCAT('%', #{peiGuangNo}, '%')


    AND pg.pei_guang_name LIKE CONCAT('%', #{peiGuangName}, '%')


    AND pg.pei_guang_status = #{peiGuangStatus}


    AND pg.pei_guang_type = #{peiGuangType}


    AND pg.lian_lu_id = #{lianLuId}


    AND pg.guan_lang_id = #{guanLangId}

ORDER BY pg.pei_guang_id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM t_zgsq_pei_guang pg
WHERE pg.deleted = 0

    AND pg.pei_guang_no LIKE CONCAT('%', #{peiGuangNo}, '%')


    AND pg.pei_guang_name LIKE CONCAT('%', #{peiGuangName}, '%')


    AND pg.pei_guang_status = #{peiGuangStatus}


    AND pg.pei_guang_type = #{peiGuangType}


    AND pg.lian_lu_id = #{lianLuId}


    AND pg.guan_lang_id = #{guanLangId}
